use proc_macro::TokenStream;
use proc_macro2::TokenStream as TokenStream2;
use quote::quote;
use syn::{parse_macro_input, Ident, ItemFn};

fn getter_impl(name: &Ident) -> TokenStream2 {
    let getter = Ident::new(&format!("get_{}", name), name.span());
    quote! {
        pub fn #getter(&self) -> &str {
            &self.#name
        }
    }
}

#[proc_macro]
pub fn make_fn(input: TokenStream) -> TokenStream {
    let name = parse_macro_input!(input as Ident);
    quote! {
        pub fn #name() -> &'static str {
            stringify!(#name)
        }
    }
    .into()
}

#[proc_macro_attribute]
pub fn with_getters(_attr: TokenStream, item: TokenStream) -> TokenStream {
    let input = parse_macro_input!(item as ItemFn);
    quote! {
        #input
    }
    .into()
}

#[proc_macro_derive(Getters, attributes(getter))]
pub fn derive_getters(item: TokenStream) -> TokenStream {
    let input = parse_macro_input!(item as syn::DeriveInput);
    let name = &input.ident;
    let getters = match &input.data {
        syn::Data::Struct(data) => data.fields.iter().map(|field| {
            let field_name = field.ident.as_ref().expect("only named fields supported");
            getter_impl(field_name)
        }),
        _ => panic!("Getters can only be derived for structs"),
    };
    let expanded = quote! {
        impl #name {
            #(#getters)*
        }
    };
    expanded.into()
}

